export function joinLoopSamples(samples,frames){const n=Math.max(1,Math.min(Math.floor(frames),Math.floor(samples.length/4))),out=new Float32Array(samples.length-n);out.set(samples.subarray(0,out.length));for(let i=0;i<n;i++){const u=i/(n-1||1),mix=u*u*(3-2*u);out[i]=samples[samples.length-n+i]*(1-mix)+samples[i]*mix;}return out;}
export function seamlessEngineLoop(context,buffer){if(!buffer?.numberOfChannels||!buffer.sampleRate)return buffer;const frames=Math.floor(buffer.sampleRate*.32),length=buffer.length-Math.min(frames,Math.floor(buffer.length/4)),out=context.createBuffer(buffer.numberOfChannels,length,buffer.sampleRate);for(let channel=0;channel<buffer.numberOfChannels;channel++)out.getChannelData(channel).set(joinLoopSamples(buffer.getChannelData(channel),frames));return out;}
